INSERT INTO `articles` (`id`, `title`, `content`, `category`, `status`, `image`, `author`, `published_date`, `created_at`, `updated_at`) VALUES
(1, 'Produk Terbaru Facial Treatment', 'Yuk, coba perawatan Ultimate Glowing Skin terbaru kami! Perawatan ini menggunakan teknologi mutakhir untuk bikin kulitmu makin kenyal, bebas kerutan, dan tampil lebih glowing. Buruan book jadwalmu sekarang dan buktikan sendiri hasilnya!\"', 'Produk', 'Published', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=800&h=500&fit=crop', 'Admin', NULL, '2026-01-21 14:06:51', '2026-04-16 14:54:27'),
(2, 'Kenali Jenis Kulitmu, Jangan Salah Pilih Produk!', 'Memilih produk skincare asal-asalan sering kali menjadi penyebab masalah kulit. Agar tidak salah langkah, kenali tipe kulit Anda:\n\n1. Oily Skin (Berminyak): Biasanya wajah terlihat mengkilap dalam waktu singkat. Anda butuh produk yang mampu menyeimbangkan minyak tanpa membuat kulit dehidrasi.\n\n2.Dry Skin (Kering): Kulit terasa tertarik, kusam, dan sering mengelupas. Kuncinya adalah hidrasi intensif dan produk yang mengunci kelembapan.\n\n3.Combination Skin (Kombinasi): Tipe paling umum, berminyak di area T-zone (dahi, hidung, dagu) tapi kering di area pipi. Perawatannya butuh keseimbangan agar tidak membuat area kering makin parah atau area berminyak makin tersumbat.\n\nMemahami tipe kulit adalah kunci agar produk Mochint Beauty yang Anda gunakan memberikan hasil maksimal. Sudah tahu tipe kulitmu yang mana?', 'Announcement', 'Published', 'https://i.pinimg.com/1200x/b7/9c/23/b79c23b447977680aa4dfd8df08e17c3.jpg', 'Admin', NULL, '2026-01-21 14:06:51', '2026-03-08 19:19:06'),
(3, 'Skin Barrier Rusak? Jangan Diabaikan!', 'Skin barrier adalah garda terdepan pelindung wajah. Jika rusak, kulit akan \"memberontak\" dengan ciri: terasa perih/panas saat memakai skincare, muncul kemerahan tanpa sebab, tekstur wajah kasar dan kusam, hingga jerawat yang terus muncul akibat bakteri yang mudah masuk.\n\nJika Anda mengalami gejala ini, segera kurangi eksfoliasi dan beralihlah ke produk yang menenangkan (soothing). Produk Mochint Beauty diformulasikan khusus untuk menjaga keseimbangan dan memperkuat skin barrier agar wajah Anda kembali sehat dan terjaga.', 'Promotion', 'Published', 'https://i.pinimg.com/736x/a6/de/fa/a6defa2ad25fa668f12993154dfbad86.jpg', 'Admin', NULL, '2026-01-21 14:06:51', '2026-03-08 20:00:14'),
(5, 'Mengapa Facial Rutin adalah Investasi Wajah', 'Banyak yang mengira facial hanya untuk \"pamer\" di media sosial. Padahal, facial rutin adalah langkah krusial dalam menjaga kesehatan kulit jangka panjang. Bayangkan wajah kita seperti rumah, mencuci muka sehari-hari hanyalah menyapu lantai, sementara facial adalah \"membersihkan debu hingga ke sudut ruangan.\"\n\nFacial membantu mengangkat tumpukan sel kulit mati dan kotoran yang menyumbat pori-pori. Jika pori-pori bersih, produk skincare yang Anda gunakan setiap hari akan bekerja 2x lebih efektif. Dengan rutin melakukan facial, sirkulasi darah di wajah meningkat, membuat wajah tampak lebih cerah, segar, dan pastinya lebih awet muda. Jangan tunggu kulit bermasalah untuk melakukan perawatan, buatlah jadwal rutin mulai sekarang!', 'Treatment', 'Published', 'https://i.pinimg.com/736x/fa/f4/70/faf4702df6b8e4a0425dd6e708e32fcd.jpg', 'Admin', NULL, '2026-02-05 18:10:47', '2026-04-24 20:12:57');
