(12, 'Faical Oil Control', '[\"Single Treatment\"]', '90 menit', 135000.00, 'Fokus menyeimbangkan produksi sebum pada kulit berminyak, membersihkan sumbatan pori, dan mencegah munculnya jerawat baru.', 'data:image/jpeg;base64,', '2026-03-12 07:24:14', '2026-04-24 19:55:42', 0, NULL, NULL, '[]'),
(13, 'Faical Whitening', '[\"Single Treatment\"]', '90 menit', 135000.00, 'Perawatan pencerahan untuk menyamarkan kusam dan meratakan warna kulit agar tampak lebih cerah, segar, dan bercahaya.', 'data:image/jpeg;base64,', '2026-03-12 07:28:21', '2026-04-24 19:55:47', 0, NULL, NULL, '[]');
INSERT INTO `treatments` (`id`, `name`, `category`, `duration`, `price`, `description`, `image`, `created_at`, `updated_at`, `discount_percentage`, `promo_start_date`, `promo_end_date`, `facilities`) VALUES
(14, 'Faical Acne', '[\"Single Treatment\"]', '90 menit', 135000.00, 'Perawatan khusus kulit berjerawat yang menenangkan inflamasi, membersihkan bakteri penyebab jerawat, dan meredakan kemerahan.', 'data:image/jpeg;base64,', '2026-03-12 07:29:27', '2026-04-24 19:55:28', 0, NULL, NULL, '[]'),
(15, 'Facial Gold', '[\"Single Treatment\"]', '90 menit', 135000.00, 'Menggunakan nutrisi emas untuk merangsang kolagen, mengencangkan kulit, serta memberikan efek anti-aging dan glowing instan.', 'data:image/jpeg;base64,', '2026-03-12 07:30:17', '2026-04-24 19:54:55', 0, NULL, NULL, '[]');
INSERT INTO `treatments` (`id`, `name`, `category`, `duration`, `price`, `description`, `image`, `created_at`, `updated_at`, `discount_percentage`, `promo_start_date`, `promo_end_date`, `facilities`) VALUES
(16, 'Facial Peeling Ultimate', '[\"Single Treatment\"]', '90 menit', 175000.00, 'Eksfoliasi kimiawi intensif untuk mempercepat regenerasi sel kulit mati yang membandel, sangat baik untuk menghaluskan tekstur kulit.', 'data:image/jpeg;base64,', '2026-03-12 07:31:02', '2026-04-24 19:55:15', 0, NULL, NULL, '[]'),
(17, 'Facial Mesotheraphy Non Needle', '[\"Single Treatment\"]', '90 menit', 175000.00, 'Teknik infus nutrisi/vitamin ke lapisan kulit tanpa jarum (Non-Needle) untuk hidrasi maksimal dan perbaikan sel kulit dari dalam.', 'data:image/jpeg;base64,', '2026-03-12 07:32:02', '2026-04-24 19:55:02', 0, NULL, NULL, '[]');
INSERT INTO `treatments` (`id`, `name`, `category`, `duration`, `price`, `description`, `image`, `created_at`, `updated_at`, `discount_percentage`, `promo_start_date`, `promo_end_date`, `facilities`) VALUES
(18, 'Facial RF Whitening Wajah', '[\"Single Treatment\"]', '90 menit', 175000.00, 'Mengombinasikan teknologi Radio Frequency untuk mengencangkan kulit sekaligus mencerahkan wajah dengan penetrasi bahan aktif pencerah.', 'data:image/jpeg;base64,', '2026-03-12 07:33:22', '2026-04-24 19:55:22', 0, NULL, NULL, '[]');
