(20, 'Faical Micro + Mesotherapy NN', '[\"Bundling Treatment\"]', '90 menit', 220000.00, 'Menggabungkan pembersihan sel mati dan nutrisi mendalam. Hasilnya, kulit beregenerasi lebih cepat dan tampak lebih sehat.', 'data:image/jpeg;base64,', '2026-03-12 07:36:24', '2026-04-24 19:54:19', 0, NULL, NULL, '[]');
INSERT INTO `treatments` (`id`, `name`, `category`, `duration`, `price`, `description`, `image`, `created_at`, `updated_at`, `discount_percentage`, `promo_start_date`, `promo_end_date`, `facilities`) VALUES
